<script setup lang="ts">
import {Head,Link,useForm,router} from '@inertiajs/vue3';
const props=defineProps<{sessions:any[],periods:any[],eligible:any[]}>();
const form=useForm({admission_period_id:props.periods.find(p=>p.is_active)?.id||'',name:'',starts_at:'',ends_at:'',location:'',maps_url:'',meeting_url:'',capacity:null as number|null,instructions:''});
const assign=(session:any)=>{const ids=Array.from(document.querySelectorAll<HTMLInputElement>(`[data-session='${session.id}']:checked`)).map(x=>x.value);if(ids.length)router.post(`/admin/test-sessions/${session.id}/assign`,{applicant_ids:ids},{preserveScroll:true});};
const result=(session:any,a:any)=>{const status=window.prompt('Status: scheduled / attending_test / passed / not_passed',a.selection_status);if(!status)return;router.patch(`/admin/test-sessions/${session.id}/applicants/${a.id}`,{attendance_status:status==='attending_test'?'attended':'assigned',selection_status:status,score:null,internal_note:null},{preserveScroll:true});};
</script>
<template><Head title="Jadwal Tes"/><main class="min-h-screen bg-slate-100 p-5"><section class="mx-auto max-w-7xl space-y-6"><div><Link href="/admin/dashboard" class="text-emerald-700">← Dashboard</Link><h1 class="text-3xl font-bold text-emerald-950">Jadwal dan hasil tes</h1></div><form @submit.prevent="form.post('/admin/test-sessions',{preserveScroll:true,onSuccess:()=>form.reset('name','starts_at','ends_at','location')})" class="grid gap-3 rounded-2xl bg-white p-5 md:grid-cols-3"><select v-model="form.admission_period_id" required class="rounded-xl border-slate-300"><option v-for="p in periods" :key="p.id" :value="p.id">{{p.name}}</option></select><input v-model="form.name" required placeholder="Nama sesi" class="rounded-xl border-slate-300"/><input v-model="form.starts_at" required type="datetime-local" class="rounded-xl border-slate-300"/><input v-model="form.ends_at" type="datetime-local" class="rounded-xl border-slate-300"/><input v-model="form.location" placeholder="Lokasi" class="rounded-xl border-slate-300"/><input v-model="form.capacity" type="number" min="1" placeholder="Kapasitas" class="rounded-xl border-slate-300"/><button class="rounded-xl bg-emerald-800 py-3 font-bold text-white">Buat sesi</button></form><article v-for="session in sessions" :key="session.id" class="rounded-2xl bg-white p-6 shadow-sm"><h2 class="text-xl font-bold text-emerald-950">{{session.name}}</h2><p class="text-sm text-slate-500">{{new Date(session.starts_at).toLocaleString('id-ID')}} · {{session.location||'Lokasi belum ditentukan'}} · {{session.applicants_count}} peserta</p><div v-if="eligible.length" class="mt-5 rounded-xl bg-emerald-50 p-4"><p class="font-semibold">Assign pendaftar memenuhi syarat</p><div class="mt-2 flex flex-wrap gap-3"><label v-for="a in eligible" :key="a.id" class="text-sm"><input :data-session="session.id" type="checkbox" :value="a.id"/> {{a.registration_number}} — {{a.full_name}}</label></div><button @click="assign(session)" class="mt-3 rounded-lg bg-emerald-800 px-4 py-2 text-sm font-bold text-white">Assign terpilih</button></div><div class="mt-5 divide-y"><div v-for="a in session.applicants" :key="a.id" class="flex justify-between gap-3 py-3"><span>{{a.registration_number}} — {{a.full_name}}</span><button @click="result(session,a)" class="rounded-lg border px-3 py-1 text-emerald-800">Ubah hasil ({{a.selection_status}})</button></div></div></article></section></main></template>
